.segment "PN_BODY_SELECT_116"
.proc PnBodySelector116


 ; All131 known original pointers are direct same-bank table entries. The
 ; 99 unsupported poses therefore retain literal originals without native
 ; pointer-reconstruction scratch writes or additional bank mappings.
 lda PnFrame
 bne :+
 ldx VvVariant
 lda PnChoosePool::StandFrames-1,x
:
 sec
 sbc $dff0
 bcs :+
 rts
:
 cmp $dff1
 bcc :+
 rts
:
 tay
 tax
 lda $dff2
 sta R0
 lda $dff3
 sta R1
 lda (R0),y
 sta R3
 lda $dff4
 sta R0
 lda $dff5
 sta R1
 lda (R0),y
 bne :+
 rts
:
 sta SmPosePtr+1
 lda R3
 sta SmPosePtr
 lda $dff8
 sta R0
 lda $dff9
 sta R1
 lda (R0),y
 bne :+
 rts
:
 lda GameEngineSubroutine
 cmp #8
 beq :+
 rts
:
 lda GuestOamRotationActive
 bne :+
 rts
:
 lda ObjectVerticalFlip
 beq :+
 rts
:
 lda Player_Y_HighPos
 cmp #1
 beq :+
 rts
:
 lda Player_Y_Position
 cmp #64
 bcs :+
 rts
:
 cmp #176
 bcc :+
 rts
:
 lda Player_X_Position
 sec
 sbc ScreenLeft_X_Pos
 tay
 lda Player_PageLoc
 sbc ScreenLeft_PageLoc
 beq :+
 rts
:
 tya
 cmp #32
 bcs :+
 rts
:
 cmp #224
 bcc :+
 rts
:
 lda CurrentOAMOffset
 clc
 adc RgOamRotation
 sta R3
 lda SmPosePtr
 sta R0
 lda SmPosePtr+1
 sta R1
 ldy #0
 lda (R0),y
 clc
 adc R3
 bcc :+
 beq :+
 rts
:
 txa
 tay
 lda $dff6
 sta R0
 lda $dff7
 sta R1
 lda (R0),y
 sta R3
 lda $dff8
 sta R0
 lda $dff9
 sta R1
 lda (R0),y
 sta SmPosePtr+1
 lda R3
 sta SmPosePtr
 rts
